<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';
require_once dirname(__DIR__,2).'/app/controllers/ApiController.php';
runApi(function(){
 requireLogin();$requested=(string)($_GET['mes']??'');$month=preg_match('/^\d{4}-\d{2}$/',$requested)&&checkdate((int)substr($requested,5,2),1,(int)substr($requested,0,4))?$requested:date('Y-m');$rows=FinancialService::extendOpenSeries(new JsonRepository('transacoes'));$accounts=(new JsonRepository('contas'))->all();$activeAccounts=array_values(array_filter($accounts,fn($a)=>!empty($a['ativa'])));$primaryAccount=null;foreach($activeAccounts as $account)if(preg_match('/principal/i',(string)($account['nome']??''))){$primaryAccount=$account;break;}if(!$primaryAccount)$primaryAccount=$activeAccounts[0]??null;$seriesCounts=[];foreach($rows as $seriesRow)if(!empty($seriesRow['serie_id']))$seriesCounts[$seriesRow['serie_id']]=($seriesCounts[$seriesRow['serie_id']]??0)+1;$summary=FinancialService::dashboard($rows,$month,$primaryAccount['id']??null);$annual=FinancialService::annualReport($rows,(int)date('Y'));$rows=filterRows(FinancialService::monthRows($rows,$month));
 $monthRows=array_values(array_filter($rows,fn($r)=>str_starts_with($r['data_vencimento'],$month)));foreach($monthRows as &$monthRow)if(!empty($monthRow['serie_id']))$monthRow['quantidade_serie']=$seriesCounts[$monthRow['serie_id']]??2;unset($monthRow);
 $recentMap=[];foreach($monthRows as $row)$recentMap[$row['id'].'|'.($row['mes_referencia']??'')]=$row;
 foreach($rows as $row)if(($row['situacao_exibida']??'')==='vencida')$recentMap[$row['id'].'|'.($row['mes_referencia']??'')]=$row;
 $recentRows=array_values($recentMap);usort($recentRows,function($a,$b){$av=($a['situacao_exibida']??'')==='vencida'?1:0;$bv=($b['situacao_exibida']??'')==='vencida'?1:0;return $av===$bv?strcmp($b['data_vencimento'],$a['data_vencimento']):$bv<=>$av;});
 usort($monthRows,fn($a,$b)=>strcmp($b['data_vencimento'],$a['data_vencimento']));
 $accountNames=[];foreach($accounts as $account)$accountNames[$account['id']]=$account['nome'];$cats=[];$incomeCats=[];$withdrawals=[];foreach($monthRows as $r){if($r['tipo']==='receita')$incomeCats[$r['categoria_nome']]=($incomeCats[$r['categoria_nome']]??0)+$r['valor_centavos'];elseif($r['tipo']==='despesa'||empty($r['conta_destino_id']))$cats[$r['categoria_nome']]=($cats[$r['categoria_nome']]??0)+$r['valor_centavos'];else{$destination=(string)($accountNames[$r['conta_destino_id']]??'Conta de destino');$withdrawals[$destination]=($withdrawals[$destination]??0)+$r['valor_centavos'];}}
 if($summary['retiradas_investimentos_mes']>0)$cats['Retiradas e investimentos']=$summary['retiradas_investimentos_mes'];
 arsort($cats);arsort($incomeCats);arsort($withdrawals);$shownCats=array_slice($cats,0,5,true);if($summary['retiradas_investimentos_mes']>0&&!array_key_exists('Retiradas e investimentos',$shownCats)){if(count($shownCats)>=5)array_pop($shownCats);$shownCats['Retiradas e investimentos']=$summary['retiradas_investimentos_mes'];}jsonResponse(['ok'=>true,'summary'=>$summary,'anual'=>$annual,'recentes'=>array_slice($recentRows,0,6),'categorias'=>$shownCats,'retiradas_investimentos'=>array_slice($withdrawals,0,5,true),'receita_categorias'=>array_slice($incomeCats,0,5,true),'mes'=>$month]);
});

